"""Package role videos, task instructions and third-party audit evidence."""
import json, html, shutil, zipfile, hashlib
from pathlib import Path
R=Path(__file__).resolve().parents[1];D=R/'docs/training';O=R/'downloads/training';stories=json.loads((D/'rendered-stories.json').read_text());labels={'npi':'NPI Admin','sub':'Subcontractor Admin','worker':'Subcontractor Worker'}
blocks=[]
for story in stories:
 role=story['role']; blocks.append(f'<section id="{role}"><h2>{labels[role]}</h2><p><a download href="{role}-walkthrough.mp4">Download video</a> · <a href="{role}-instructions.md">Written instructions</a> · <a href="{role}-captions.vtt">Captions</a></p><video controls preload="metadata" src="{role}-walkthrough.mp4"><track kind="captions" src="{role}-captions.vtt" srclang="en" label="English" default></video>')
 for scene,chapter in zip(story['scenes'],story['chapters']):
  t=chapter['start'];stamp=f'{int(t//60)}:{int(t%60):02}'
  blocks.append(f'<article><h3>{html.escape(scene["title"])}</h3><button onclick="const v=this.closest(\'section\').querySelector(\'video\');v.currentTime={t};v.play()">Watch at {stamp}</button><p>{html.escape(scene["text"])}</p></article>')
 blocks.append('</section>')
style='body{font:17px/1.65 system-ui;color:#172f47;background:#f4f7fb;max-width:1050px;margin:auto;padding:28px}header,section{background:white;padding:28px;margin:20px 0;border:1px solid #d7e1ec;border-radius:14px}h1,h2,h3{line-height:1.2}h2{border-bottom:3px solid #d7ad49;padding-bottom:15px}video{display:block;width:100%;max-height:80vh;background:#0b1d30}a{color:#245797}article{border-top:1px solid #d7e1ec;padding:14px 0}button{border:1px solid #afc1d6;border-radius:7px;background:#f2f6fb;color:#173c67;padding:8px 12px;font:inherit;cursor:pointer}nav{display:flex;flex-wrap:wrap;gap:20px}.note{border-left:4px solid #d7ad49;padding-left:15px}@media(max-width:600px){body{padding:10px}header,section{padding:16px}}'
intro='''<header><p>ALASKA NPI · OPERATIONS TRAINING</p><h1>Three views. One clear approval process.</h1><p><strong>NPI sets the responsibility → company assigns and reviews → workers record work → NPI verifies.</strong></p><nav><a href="#npi">NPI Admin</a><a href="#sub">Subcontractor Admin</a><a href="#worker">Worker</a><a href="audit/index.html">Audit report</a><a download href="app-package/NPI-Alaska-Operations-v1.0.zip">App ZIP</a></nav><p class="note">Actual running app screens with fictional training records and simulated cloud/GPS responses. These videos do not prove that your deployed backend is configured. Synthetic female narration uses an Australian-English synthetic reference; accent consistency may vary. No human presenter is shown.</p><p>Setup dialogs show what to enter; no production settings were saved. The worker recording performs test attendance and submission. The 1.75-hour figure is a test fixture, not the filming duration. Some frames are held to finish the explanation.</p></header>'''
footer='''<section><h2>Daily checklist and help</h2><p><strong>Worker:</strong> correct assignment → fresh check-in location → complete tasks → actual work photos → fresh checkout location → submit hours.</p><p><strong>Company:</strong> approve genuine worker accounts → assign work → inspect attendance and evidence → approve and forward, or request correction.</p><p><strong>NPI:</strong> verify company, location, original attendance, evidence and the recorded/claimed comparison → accept or return with a reason.</p><h3>Where data is stored</h3><p>Supabase is the primary database and account service. Uploaded work evidence belongs in private Supabase Storage. Google Sheets is the management table view and controlled change route; it does not look identical to the app. Original attendance must not be overwritten by spreadsheet edits. Cloudflare serves the app frontend.</p><h3>Install and use the PWA</h3><p>Open the deployed HTTPS app in your phone browser. On Android use Install app / Add to Home screen; on iPhone use Share → Add to Home Screen. Allow location when recording attendance. Use a working internet connection: this release has no offline write queue. Reloading ends the session; sign in again to access saved records.</p><h3>If something fails</h3><p>No assignment: ask the company administrator. Account pending: wait for their approval. GPS failure: allow precise location, check the connection and retry. Wrong hours: explain a corrected claim; do not modify original attendance. Missing company site: the company asks NPI to assign its contract/site scope. Password help: contact your company administrator; they contact NPI for administrator account issues.</p><h3>Current release boundary</h3><p>Operations tracking only. Rates, invoices, contractor bills and customer billing are deferred. A reference picture identifies a building; it is not completed-work evidence. Never enter real passwords in shared training recordings.</p><p><a href="MEDIA-SOURCES.md">Narration sources and reproduction notes</a> · <a href="audit/index.html">Automated audit and remaining acceptance checks</a></p></section>'''
(O/'START-HERE.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NPI — Three-role training</title><style>'+style+'</style></head><body>'+intro+''.join(blocks)+footer+'</body></html>')
app=O/'app-package';app.mkdir(exist_ok=True);shutil.copy(R/'downloads/NPI-Alaska-Operations-v1.0.zip',app/'NPI-Alaska-Operations-v1.0.zip')
shutil.copy(D/'MEDIA-SOURCES.md',O/'MEDIA-SOURCES.md');shutil.copy(D/'VERIFICATION.md',O/'VERIFICATION.md');shutil.copy('/usr/share/common-licenses/GPL-2',O/'AUDIO-GPL-2.txt');shutil.copytree(R/'docs/external-audit',O/'audit',dirs_exist_ok=True)
source=O/'generation-source';source.mkdir(exist_ok=True)
for name in ['record-role-training.mjs','render-role-training.py','package-role-training.py']:shutil.copy(R/'scripts'/name,source/name)
shutil.copy(D/'stories.json',source/'stories.json')
shutil.copy(R/'tests/helpers/live-fixture.js',source/'live-fixture.js')
(O/'README.txt').write_text('NPI THREE-ROLE TRAINING AND AUDIT\n\nExtract the ZIP completely, then open START-HERE.html.\nDouble-click each MP4 if your browser blocks local playback.\nVideos include burned-in captions; VTT files provide separate captions.\nRole instructions and chapter times are included.\nAudit reports are local frontend checks, not a cloud security certification.\nThe original Operations app ZIP is included in app-package/. Its approved UI is preserved. Installing this guide does not redeploy your app.\n')
files={str(p.relative_to(O)):hashlib.sha256(p.read_bytes()).hexdigest()for p in O.rglob('*')if p.is_file()and p.name!='SHA256SUMS.json'}
(O/'SHA256SUMS.json').write_text(json.dumps(files,indent=2))
target=R/'downloads/NPI-Training-and-Audit.zip'
with zipfile.ZipFile(target,'w',zipfile.ZIP_DEFLATED)as z:
 for p in O.rglob('*'):
  if p.is_file():z.write(p,'NPI-Training-and-Audit/'+str(p.relative_to(O)))
print(target, target.stat().st_size, hashlib.sha256(target.read_bytes()).hexdigest())
